    for (int i = 0; i < charCount; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            utf8Length += 1;
        } else if (c <= 0x7FF) {
            utf8Length += 2;
        } else if (c < 0xD800 || c > 0xDBFF) {
            utf8Length += 3;
        } else {
            i++;
            utf8Length += 4;
        }
    }

    if (lb.offset + utf8Length > lb.buffer.length) {
        lb = LinkedBuffer.expand(lb, utf8Length);
    }

